mapper.select:
SELECT so.id, so.code, so.so_id, so.so_code, so.source_code, so.source_id, so.order_type, so.approve_status, so.warehouse_org_name, so.carrier_id, so.invalid_status, so.plan_delivery_date, so.actual_delivery_date, so.pack_date, so.warehouse_id, so.warehouse_name, so.approve_user_name, so.create_user_name, so.create_time, sod.sku_id, sod.sku_no, sod.plan_qty, sod.actual_qty, sod.source_detail_id, sod.warehouse_location FROM so_outstock so INNER JOIN so_outstock_detail sod ON so.id=sod.main_id AND sod.is_deleted=FALSE WHERE so.is_deleted=FALSE
AND sod.sku_no IN
#{skuNo}
AND so.code ILIKE concat('%', #{params.code} ,'%')
AND so.so_code ILIKE concat('%', #{params.soCode} ,'%')
AND so.order_type =#{params.orderType}
AND so.approve_status IN
#{approveStatus}
AND so.invalid_status =#{params.invalidStatus}
AND so.customer_id IN
#{customerId}
AND so.warehouse_id IN
#{warehouseId}
AND so.create_time >= #{params.createTimeList[0]} and (#{params.createTimeList[1]}::TIMESTAMP + INTERVAL '1 DAY' ) > so.create_time
AND so.actual_delivery_date >= #{params.actualDeliveryDateList[0]} and (#{params.actualDeliveryDateList[1]}::TIMESTAMP + INTERVAL '1 DAY' ) > so.actual_delivery_date
AND so.create_user_id IN
#{createUserId}
AND so.approve_status IN
#{approve}
${params.permissionSql}
ORDER BY so.create_time DESC

SELECT so.id, so.code, so.so_id, so.so_code, so.order_type, so.source_id, so.source_code, so.approve_status, so.warehouse_org_name, so.carrier_id, so.invalid_status, so.plan_delivery_date, so.actual_delivery_date, so.pack_date, so.warehouse_id, so.warehouse_name, so.approve_user_name, so.create_user_name, so.create_time, sod.sku_id, sod.sku_no, sod.plan_qty, sod.actual_qty, sod.source_detail_id, sod.warehouse_location FROM so_outstock so INNER JOIN so_outstock_detail sod ON so.id=sod.main_id AND sod.is_deleted=FALSE WHERE so.is_deleted=FALSE
AND so.id IN
#{id}
AND sod.sku_no IN
#{skuNo}
AND so.code ILIKE concat('%', #{params.code} ,'%')
AND so.so_code ILIKE concat('%', #{params.soCode} ,'%')
AND so.order_type =#{params.orderType}
AND so.approve_status IN
#{approveStatus}
AND so.invalid_status =#{params.invalidStatus}
AND so.customer_id IN
#{customerId}
AND so.warehouse_id IN
#{warehouseId}
AND so.create_time >= #{params.createTimeList[0]} and (#{params.createTimeList[1]}::TIMESTAMP + INTERVAL '1 DAY' ) > so.create_time
AND so.actual_delivery_date >= #{params.actualDeliveryDateList[0]} and (#{params.actualDeliveryDateList[1]}::TIMESTAMP + INTERVAL '1 DAY' ) > so.actual_delivery_date
AND so.create_user_id IN
#{createUserId}
AND so.approve_status IN
#{approve}
${params.permissionSql}
ORDER BY so.create_time DESC

SELECT so.warehouse_id, so.id AS sourceId, so.code AS sourceCode, sod.id AS sourceDetailId, sod.sku_id,sod.sku_no, sod.warehouse_location, sod.actual_qty AS qty FROM so_outstock so INNER JOIN so_outstock_detail sod ON sod.main_id=so.id AND sod.is_deleted=FALSE WHERE so.is_deleted=FALSE
AND so.id IN
#{id}

SELECT approve_status, count(*) FROM so_outstock WHERE is_deleted=FALSE
${permissionSql}
GROUP BY approve_status
